import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const stateFile = resolve(dirname(fileURLToPath(import.meta.url)), '../target/ticket-state');
const transitions = {
  draft: { open: 'open' },
  open: { close: 'closed' },
  closed: { reopen: 'open' },
};

let state = 'draft';

try {
  state = readFileSync(stateFile, 'utf8').trim();
} catch (error) {
  if (error.code !== 'ENOENT') {
    throw error;
  }
}

if (!Object.hasOwn(transitions, state)) {
  throw new Error(`Invalid stored ticket state: ${state}`);
}

const actions = process.argv.slice(2);

if (actions.length === 0) {
  console.log(state);
} else {
  const [action] = actions;
  const nextState =
    actions.length === 1 && Object.hasOwn(transitions[state], action)
      ? transitions[state][action]
      : undefined;

  if (nextState === undefined) {
    console.error(`Invalid transition: ${state} -> ${actions.join(' ')}`);
    process.exitCode = 1;
  } else {
    mkdirSync(dirname(stateFile), { recursive: true });
    writeFileSync(stateFile, nextState);
    console.log(nextState);
  }
}

